package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import org.junit.jupiter.api.*;import java.util.*;import java.util.function.Function;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real candidate/journal/decision schema and CAS. Evaluation metadata is an explicit private-proof fixture; no accepting professional evidence is fabricated. */
class FormalAcceptanceDecisionTest {
 FormalAgentCandidateServiceTest f;FormalAgentAcceptanceService service;FormalAgentAcceptanceMapper rows;FormalAgentAcceptanceEvidence evidence;ApplicationSessionIdentity.Verified subject;JsonNode request;boolean cas=true;
 @BeforeEach void setup()throws Exception{f=new FormalAgentCandidateServiceTest();f.author();f.actor=f.id(3);var access=mock(EnterpriseAccess.class);subject=mock(ApplicationSessionIdentity.Verified.class);when(access.execute(eq(subject),any())).thenAnswer(i->((Function<EnterpriseAccess.Admission,Object>)i.getArgument(1)).apply(f.a));rows=mock(FormalAgentAcceptanceMapper.class);evidence=mock(FormalAgentAcceptanceEvidence.class);var evaluations=mock(EvaluationService.class);var metadata=mock(EvaluationService.FormalDefinitionMetadata.class);var row=mock(EvaluationService.FormalDefinitionIdentity.class);when(row.contentHash()).thenReturn(f.H);when(row.evaluationId()).thenReturn(f.id(601));when(row.classification()).thenReturn("INTERNAL");when(metadata.row()).thenReturn(row);var definition=mock(EvaluationProtocol.Definition.class);var create=mock(EvaluationProtocol.Create.class);when(create.candidates()).thenReturn(List.of(new PermissionProtocol.Basis(f.binding.versionId(),f.binding.contentSha256())));when(definition.request()).thenReturn(create);when(metadata.definition()).thenReturn(definition);when(evaluations.requireFormalDefinitionMetadata(eq(f.a),eq(f.id(601)))).thenReturn(metadata);when(rows.decideCandidate(anyMap())).thenAnswer(i->{if(!cas)return 0;Map<String,Object>v=i.getArgument(0);var a=f.agent;f.agent=new AgentPublicationMapper.Agent(a.tenantId(),a.projectId(),a.agentId(),a.versionId(),a.name(),a.dependencyManifest(),a.limits(),(String)v.get("evaluationId"),a.contentSha256(),(String)v.get("status"),a.schemaVersion(),a.schemaManifest(),a.createdBy(),a.createdAt(),a.classification(),a.revision().add(java.math.BigInteger.ONE));return 1;});service=new FormalAgentAcceptanceService(access,f.formal,f.json,evidence,f.store,mock(FormalAgentAcceptanceStore.class),f.journal,f.guarded,rows,f.resources,evaluations);var n=f.json.object().put("schema_version","1.0.0").put("decision","REJECT").put("reason","Real review rejected fixed candidate").put("expected_revision","1");n.set("candidate",f.json.tree(new PermissionProtocol.Basis(f.binding.versionId(),f.binding.contentSha256())));n.set("evaluation",f.json.tree(new PermissionProtocol.Basis(f.id(601),f.H)));n.set("statistics_policy",f.json.tree(new PermissionProtocol.Basis(f.id(602),f.H)));n.putArray("score_bindings");request=n;}
 JsonNode decide()throws Exception{return service.decide(subject,"1","original-acceptance-decision",f.formal.canonical(request).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 @Test void rejectionStoresOriginalDecisionButCannotCreateAcceptedSidecar()throws Exception{var result=decide();assertEquals("DRAFT",f.agent.status());assertEquals("REJECT",service.read(subject,"1",result.path("resource_id").asText()).path("decision").asText());verify(rows,never()).insertAcceptance(anyMap());verifyNoInteractions(evidence);}
 @Test void authorCannotApproveOrRejectOwnCandidate()throws Exception{f.actor=f.binding.createdBy();assertThrows(TenantAccessException.class,this::decide);verify(rows,never()).decideCandidate(anyMap());}
 @Test void originalReplayDoesNotNeedRetainedPublishPermission()throws Exception{var r=decide();when(f.resources.require(eq(f.a),any(),eq("agent.publish"),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertEquals(r,decide());verify(rows,times(1)).decideCandidate(anyMap());}
 @Test void sameKeyChangedDecisionBodyConflicts()throws Exception{decide();((com.fasterxml.jackson.databind.node.ObjectNode)request).put("reason","Altered original reason");assertThrows(TenantAccessException.class,this::decide);verify(rows,times(1)).decideCandidate(anyMap());}
 @Test void currentReadRevocationBlocksOriginalReceipt()throws Exception{var r=decide();when(f.resources.require(eq(f.a),any(),eq("configuration.read"),anyString())).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->service.receipt(subject,"1",r.path("resource_id").asText(),r.path("operation_id").asText()));}
 @Test void missingOriginalAuditBlocksHistory()throws Exception{var r=decide();f.audits.clear();assertThrows(TenantAccessException.class,()->service.read(subject,"1",r.path("resource_id").asText()));}
}
